import{_ as s,o as n,c as t,ah as r}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Inscriptions et paiements","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/caissier/inscriptions-et-paiements.md","filePath":"src/guide/caissier/inscriptions-et-paiements.md"}'),i={name:"guide/caissier/inscriptions-et-paiements.md"};function a(o,e,l,u,c,p){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="inscriptions-et-paiements" tabindex="-1">Inscriptions et paiements <a class="header-anchor" href="#inscriptions-et-paiements" aria-label="Permalink to &quot;Inscriptions et paiements&quot;">​</a></h1><p>Cette page couvre les deux moments où la caisse intervient dans le parcours d&#39;un élève : la saisie d&#39;un nouveau dossier pour une famille présente sur site, et le suivi financier d&#39;un élève déjà inscrit — frais, paiements, remises et échéancier — depuis <strong>Facturation</strong>.</p><h2 id="saisir-un-dossier-pour-une-famille-sur-site" tabindex="-1">Saisir un dossier pour une famille sur site <a class="header-anchor" href="#saisir-un-dossier-pour-une-famille-sur-site" aria-label="Permalink to &quot;Saisir un dossier pour une famille sur site&quot;">​</a></h2><p>Quand une famille se présente directement à la caisse plutôt que de remplir le formulaire en ligne, c&#39;est vous qui déposez son dossier de candidature.</p><ol><li>Ouvrez <strong>Élèves et admissions → Nouveau dossier</strong>.</li><li>Renseignez le <strong>Prénom</strong>, le <strong>Nom</strong> et la <strong>Date de naissance</strong> de l&#39;élève, puis le <strong>Site</strong> et le <strong>Département</strong> souhaités.</li><li>Ajoutez au moins un <strong>Parent / tuteur</strong> : prénom, nom, e-mail, téléphone (facultatif) et lien de parenté (<strong>Père</strong>, <strong>Mère</strong>, <strong>Tuteur légal</strong> ou <strong>Autre</strong>). Cochez <strong>Contact principal</strong> pour la personne à contacter en priorité. Utilisez <strong>Ajouter un tuteur</strong> pour en saisir plusieurs.</li><li>Cliquez sur <strong>Envoyer le dossier</strong>.</li></ol><p>Ce dossier rejoint la même file d&#39;attente que les candidatures reçues en ligne, avec le canal <strong>Caisse</strong> — c&#39;est le secrétariat qui l&#39;examine et décide de l&#39;affecter à une classe. Voir <a href="/era-guide/guide/secretariat/candidatures.html">Candidatures</a>.</p><div class="tip custom-block"><p class="custom-block-title">Mode hors ligne</p><p>Si votre poste n&#39;a pas de connexion au moment de la saisie, le formulaire reste utilisable : le dossier est mis en attente et envoyé automatiquement au retour de la connexion. Vous ne pouvez toutefois pas joindre de documents hors ligne — ajoutez-les une fois reconnecté. Un bandeau en haut de la page indique le nombre de dossiers en attente de synchronisation, avec un bouton <strong>Synchroniser maintenant</strong> dès que vous êtes de nouveau en ligne.</p></div><h2 id="suivre-les-frais-et-paiements-d-un-eleve" tabindex="-1">Suivre les frais et paiements d&#39;un élève <a class="header-anchor" href="#suivre-les-frais-et-paiements-d-un-eleve" aria-label="Permalink to &quot;Suivre les frais et paiements d&#39;un élève&quot;">​</a></h2><p>Une fois qu&#39;un dossier est validé par le secrétariat, l&#39;élève apparaît dans <strong>Facturation</strong>. La liste est filtrable par nom d&#39;élève et par année scolaire, et affiche pour chacun le total dû, le total payé et le solde restant. Le bouton <strong>En retard</strong> ne garde que les élèves en retard sur leur échéancier ; pour chacun, le montant en retard s&#39;affiche en rouge sous le solde. Cliquez sur <strong>Voir</strong> pour ouvrir le dossier financier complet d&#39;un élève.</p><p>La page de détail affiche quatre chiffres clés : <strong>Total dû</strong>, <strong>Remise</strong>, <strong>Total payé</strong> et <strong>Solde</strong>.</p><h3 id="definir-les-frais-dus" tabindex="-1">Définir les frais dus <a class="header-anchor" href="#definir-les-frais-dus" aria-label="Permalink to &quot;Définir les frais dus&quot;">​</a></h3><p>Si une grille de frais existe pour le site, le département et l&#39;année scolaire de l&#39;élève, elle apparaît sous <strong>Articles de frais</strong> : les articles obligatoires sont listés directement, et les articles optionnels (par exemple la cantine ou le transport) sont proposés sous forme de cases à cocher — cochez celles qui s&#39;appliquent à cet élève, puis cliquez sur <strong>Enregistrer les modifications</strong>.</p><p>Pour un élève déjà inscrit l&#39;année précédente, un encadré rappelle ses options de cette année-là (<strong>Options de 2026-2027 : Cantine, …</strong>). Le bouton <strong>Reprendre ces options</strong> coche les mêmes articles dans la grille de cette année ; une option absente de la nouvelle grille est signalée. Rien n&#39;est facturé tant que vous n&#39;avez pas cliqué sur <strong>Enregistrer les modifications</strong> : vérifiez d&#39;abord avec la famille.</p><p>Si aucune grille de frais n&#39;est configurée pour ce site, ce département et cette année scolaire, la page vous l&#39;indique — dans ce cas, demandez à un administrateur de la créer avant de pouvoir facturer l&#39;élève.</p><h3 id="encaisser-un-paiement" tabindex="-1">Encaisser un paiement <a class="header-anchor" href="#encaisser-un-paiement" aria-label="Permalink to &quot;Encaisser un paiement&quot;">​</a></h3><ol><li>Dans le formulaire <strong>Enregistrer un paiement</strong>, saisissez le <strong>Montant</strong>.</li><li>Choisissez la <strong>Méthode</strong> : Mixx by Yass, Flooz, T-Money, Carte bancaire ou Dépôt bancaire.</li><li>Si une grille de frais existe, indiquez à quel <strong>Article de frais</strong> se rattache ce paiement, ou laissez le choix <strong>Somme globale (non liée à un article)</strong> pour un versement qui ne correspond à aucun article précis.</li><li>Renseignez la <strong>Référence</strong> (numéro de transaction, de chèque, etc.) si vous en avez une, la date à laquelle le paiement a été <strong>payé</strong>, et d&#39;éventuelles <strong>Notes</strong>.</li><li>Cliquez sur <strong>Enregistrer le paiement</strong>.</li></ol><p>Le paiement apparaît dans la liste <strong>Paiements</strong> de l&#39;élève, avec un reçu généré automatiquement — cliquez sur <strong>Télécharger le reçu</strong> sur la ligne du paiement pour l&#39;imprimer ou le remettre à la famille. Les parents ou tuteurs de l&#39;élève reçoivent aussi une notification les informant du paiement et du solde restant.</p><p>Pour supprimer un paiement saisi par erreur, cliquez sur <strong>Supprimer</strong> sur sa ligne puis confirmez — cette action est définitive.</p><div class="tip custom-block"><p class="custom-block-title">Mode hors ligne</p><p>Un paiement peut être encaissé même sans connexion : il apparaît dans une section <strong>En attente de synchronisation</strong> jusqu&#39;au retour de la connexion, puis se synchronise automatiquement (ou via <strong>Synchroniser maintenant</strong>).</p></div><h3 id="mettre-en-place-un-echeancier-de-paiement" tabindex="-1">Mettre en place un échéancier de paiement <a class="header-anchor" href="#mettre-en-place-un-echeancier-de-paiement" aria-label="Permalink to &quot;Mettre en place un échéancier de paiement&quot;">​</a></h3><p>Pour étaler les frais d&#39;un élève sur plusieurs versements plutôt que d&#39;attendre un paiement unique :</p><ol><li>Dans le bloc <strong>Plan de paiement</strong>, cliquez sur <strong>Ajouter une tranche</strong> pour chaque échéance souhaitée.</li><li>Pour chaque tranche, renseignez un <strong>Libellé</strong> (par exemple « 1ère tranche »), un <strong>Montant</strong> et une <strong>Date d&#39;échéance</strong>.</li><li>Cliquez sur <strong>Enregistrer le plan de paiement</strong>.</li></ol><p>Chaque tranche affiche ensuite un statut : <strong>À venir</strong>, <strong>Payée</strong> ou <strong>En retard</strong>, selon la date d&#39;échéance et les paiements déjà reçus. Une tranche passe en retard le lendemain de sa date d&#39;échéance si les paiements ne la couvrent pas encore. Mettre en place un nouveau plan remplace automatiquement l&#39;ancien s&#39;il en existait un. Pour supprimer un plan sans le remplacer, cliquez sur <strong>Supprimer</strong> au-dessus du tableau des tranches et confirmez.</p><h3 id="consulter-et-appliquer-une-remise" tabindex="-1">Consulter et appliquer une remise <a class="header-anchor" href="#consulter-et-appliquer-une-remise" aria-label="Permalink to &quot;Consulter et appliquer une remise&quot;">​</a></h3><p>Les remises accordées à un élève (libellé, montant fixe ou pourcentage, motif, et qui l&#39;a accordée) sont visibles par tous dans le bloc <strong>Remises</strong> du dossier financier.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Accorder ou retirer une remise est réservé aux comptes administrateur. Si vous êtes connecté en tant que caisse, vous voyez les remises existantes mais pas le formulaire <strong>Accorder une remise</strong> — demandez à un administrateur d&#39;ouvrir ce même dossier pour l&#39;ajouter :</p><ol><li>Renseignez le <strong>Libellé</strong> de la remise (ce qu&#39;elle représente).</li><li>Choisissez le <strong>Type</strong> : <strong>Montant fixe</strong> ou <strong>Pourcentage</strong>.</li><li>Renseignez la <strong>Valeur</strong> correspondante.</li><li>Indiquez le <strong>Motif</strong> de la remise (facultatif).</li><li>Cliquez sur <strong>Accorder la remise</strong>.</li></ol></div><p>Une remise accordée réduit immédiatement le <strong>Total dû</strong> affiché sur la page.</p>',27)])])}const m=s(i,[["render",a]]);export{g as __pageData,m as default};
